const typeNames = {
  explain: { en: 'Explain the behavior', ru: 'Объясните поведение', es: 'Explica el comportamiento' },
  predict: { en: 'Predict the output', ru: 'Предскажите вывод', es: 'Predice la salida' },
  review: { en: 'Review the code', ru: 'Проведите ревью кода', es: 'Revisa el código' },
  scenario: { en: 'Senior scenario', ru: 'Сценарий для senior', es: 'Escenario senior' },
};

const makeCopy = (kind, locale, [topic, prompt, hint, rule, answer]) => ({
  type: typeNames[kind][locale], topic, prompt, hint, keyPoints: [hint, rule], answer,
});

const q = ({ id, track, section, topicKey, difficulty, kind, tags = [], en, ru, es }) => ({
  id, track, section, topicKey, difficulty, tags, versions: [],
  content: { en: makeCopy(kind, 'en', en), ru: makeCopy(kind, 'ru', ru), es: makeCopy(kind, 'es', es) },
});

