export const frontendQuestions = allQuestions.map((question) => exampleFiles[question.id]
  ? { ...question, example: { context: { en: question.content.en.hint, ru: question.content.ru.hint, es: question.content.es.hint }, files: exampleFiles[question.id] } }
  : question);

const lookupQuestionIds = ['js-event-loop-microtasks', 'js-promise-combinators', 'js-abort-controller', 'js-fetch-http-errors', 'html-semantic-landmarks', 'html-button-link-dialog', 'css-cascade-layers', 'css-container-queries'];
export const frontendLookupEntries = lookupQuestionIds.map((questionId) => {
  const question = frontendQuestions.find(({ id }) => id === questionId);
  const build = (locale) => ({ title: question.content[locale].topic, useWhen: question.content[locale].hint, typical: question.content[locale].keyPoints[1], trap: question.content[locale].answer });
  return { id: `lookup-${questionId}`, track: question.track, aliases: [question.topicKey, questionId], content: { en: build('en'), ru: build('ru'), es: build('es') } };
});

